<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {useRoute} from 'vue-router';import {companyOptions,api,date,errorText,currentPeriod,statusLabels} from '../api';import {useAuth} from '../stores/auth';import PageHeading from '../components/PageHeading.vue';import StatusBadge from '../components/StatusBadge.vue';import Modal from '../components/Modal.vue';import {Plus,ArrowRight,Check} from 'lucide-vue-next';
const auth=useAuth(),route=useRoute(),works=ref<any[]>([]),companies=ref<any[]>([]),period=ref(currentPeriod()),status=ref(String(route.query.status||'')),error=ref(''),busy=ref(false),loading=ref(true),show=ref(false),selected=ref<any>(null),nextStatus=ref(''),reason=ref('');const form=ref({company_id:Number(route.query.company_id)||'',title:'Contabilidad mensual',period:period.value,due_on:''});const transitions:Record<string,string[]>={not_started:['waiting','preparing','cancelled'],waiting:['preparing','cancelled'],preparing:['review','waiting','cancelled'],review:['changes','approved','cancelled'],changes:['preparing','review','cancelled'],approved:['delivered','changes'],delivered:['changes'],cancelled:['not_started']};const available=computed(()=>(transitions[selected.value?.status]||[]).filter(s=>auth.reviewer||!['approved','delivered','changes'].includes(s)));
async function load(){loading.value=true;error.value='';try{works.value=(await api.get('/works',{params:{period:period.value,status:status.value||undefined,company_id:route.query.company_id}})).data;}catch(e){error.value=errorText(e);}finally{loading.value=false;}}
async function create(){busy.value=true;try{await api.post('/works',{...form.value,due_on:form.value.due_on||null});show.value=false;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function open(w:any){selected.value=structuredClone(w);nextStatus.value='';reason.value='';error.value='';}
async function checklist(){busy.value=true;try{selected.value=(await api.put(`/works/${selected.value.id}/checklist`,{version:selected.value.version,checklist:selected.value.checklist})).data;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function transition(){busy.value=true;try{await api.patch(`/works/${selected.value.id}`,{version:selected.value.version,status:nextStatus.value,reason:reason.value});selected.value=null;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
onMounted(async()=>{await load();if(auth.staff)try{companies.value=await companyOptions();}catch(e){error.value=errorText(e);}});
</script>
<template><PageHeading title="Trabajos por período" subtitle="Del primer antecedente a la entrega final."><button v-if="auth.staff" class="button primary" @click="show=true"><Plus :size="16"/>Nuevo trabajo</button></PageHeading><div class="toolbar"><label class="inline-label">Período<input type="month" v-model="period" @change="load"></label><label class="inline-label">Estado<select v-model="status" @change="load"><option value="">Todos los estados</option><option v-for="s in Object.keys(transitions)" :key="s" :value="s">{{statusLabels[s]}}</option></select></label></div><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="loading" class="empty">Cargando trabajos…</div><section v-else class="panel"><div class="table-wrap"><table><thead><tr><th>Empresa / Trabajo</th><th>Estado</th><th>Antecedentes</th><th>Fecha interna</th><th></th></tr></thead><tbody><tr v-for="w in works" :key="w.id"><td><strong>{{w.company.name}}</strong><small>{{w.title}} · {{w.period}}</small></td><td><StatusBadge :status="w.status"/></td><td>{{w.requests.filter((r:any)=>['accepted','not_applicable'].includes(r.status)).length}} / {{w.requests.length}} resueltos</td><td>{{date(w.due_on)}}</td><td><button class="button" @click="open(w)">Ver detalle <ArrowRight :size="14"/></button></td></tr></tbody></table><p v-if="!works.length" class="empty">No hay trabajos para este período.</p></div></section><Modal v-if="show" title="Nuevo trabajo" @close="show=false"><form @submit.prevent="create" class="form-grid"><label class="span-two">Empresa<select v-model="form.company_id" required><option value="" disabled>Selecciona una empresa</option><option v-for="c in companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="span-two">Servicio / Nombre<input v-model="form.title" required maxlength="180"></label><label>Período<input type="month" v-model="form.period" required></label><label>Fecha interna<input type="date" v-model="form.due_on"></label><p class="error span-two" v-if="error">{{error}}</p><div class="form-footer"><button class="button primary" :disabled="busy">Crear trabajo</button></div></form></Modal><Modal v-if="selected" :title="selected.title" @close="selected=null"><p>{{selected.period}} · <StatusBadge :status="selected.status"/></p><h3 class="section-label">Lista de verificación</h3><label class="checklist-item" v-for="(item,i) in selected.checklist" :key="i"><input type="checkbox" v-model="item.done" :disabled="!auth.staff||['approved','delivered','cancelled'].includes(selected.status)">{{item.title}}</label><button v-if="auth.staff&&!['approved','delivered','cancelled'].includes(selected.status)" class="button" @click="checklist" :disabled="busy"><Check :size="15"/>Guardar lista</button><RouterLink :to="`/documents?work_item_id=${selected.id}`" class="panel-link" @click="selected=null">Ver antecedentes de este trabajo →</RouterLink><form v-if="auth.staff&&available.length" @submit.prevent="transition" class="stack-form"><label>Siguiente etapa<select v-model="nextStatus" required><option value="" disabled>Selecciona una etapa</option><option v-for="s in available" :key="s" :value="s">{{statusLabels[s]}}</option></select></label><label>Motivo del cambio<textarea v-model="reason" placeholder="Obligatorio para ajustes, cancelación y reapertura." maxlength="2000"></textarea></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="button primary" :disabled="busy">Actualizar etapa</button></form></Modal></template>
